'use strict';
(async()=>{
const $=s=>document.querySelector(s),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function request(path,options={}){const r=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options,signal:AbortSignal.timeout(15000)}),data=await r.json();if(!r.ok)throw Error(data.error?.message||'Please try again.');return data}
const consent=()=>{try{return localStorage.getItem('reposhelf.analytics.consent.v1')==='yes'}catch{return false}},saveConsent=value=>{localStorage.setItem('reposhelf.analytics.consent.v1',value?'yes':'no');if(!value){localStorage.removeItem('reposhelf.analytics.visitor');sessionStorage.removeItem('reposhelf.analytics.session')}};
try{const config=await request('/api/auth?action=legal');$('#legal-operator').innerHTML=config.active?`<p class="legal-meta">Operator: ${esc(config.operator)} · ${esc(config.country)} · <a href="mailto:${esc(config.contactEmail)}">${esc(config.contactEmail)}</a></p>`:'<p class="legal-notice">Draft: operator details are awaiting configuration. Account agreement acceptance is not yet activated.</p>';document.querySelectorAll('.legal-contact').forEach(el=>{el.innerHTML=config.active?`<a href="mailto:${esc(config.contactEmail)}">${esc(config.contactEmail)}</a>`:'contact details will be published before activation'});
if($('#privacy-analytics')){$('#privacy-analytics').checked=consent();$('#save-privacy').onclick=()=>{try{saveConsent($('#privacy-analytics').checked);$('#privacy-message').textContent='Preference saved for this browser.'}catch{$('#privacy-message').textContent='Your browser could not save this preference. Analytics remains off unless an earlier preference was saved.'}}}
if(!$('#legal-session'))return;const session=await request('/api/auth');if(!session.user){$('#legal-session').innerHTML='<p>Sign in with GitHub to review your account agreement.</p><a class="button lime" href="/api/auth?action=start">Sign in with GitHub ↗</a>';return}
$('#legal-session').innerHTML=`<p>Signed in as <strong>${esc(session.user.name)}</strong>.</p>`;if(!config.active){$('#legal-message').textContent='Legal setup is awaiting the operator’s contact details. You can continue browsing.';return}if(session.legal?.ready===false){$('#legal-message').textContent='A database update is needed before acceptance can be recorded. Ask the administrator to apply migration 5.';return}if(!session.legal?.required){$('#legal-session').innerHTML+='<p>You have accepted the current Terms of Service and acknowledged the Privacy Policy.</p><a class="button lime" href="/">Continue to RepoShelf</a>';return}
$('#legal-accept-form').hidden=false;$('#agree-legal').onchange=()=>$('#accept-button').disabled=!$('#agree-legal').checked;
$('#legal-accept-form').onsubmit=async e=>{e.preventDefault();if(!$('#agree-legal').checked)return;$('#accept-button').disabled=true;try{await request('/api/auth?action=accept-legal',{method:'POST',body:JSON.stringify({terms:config.version,privacy:config.version,agree:true})});try{saveConsent($('#accept-analytics').checked)}catch{$('#legal-message').textContent='Agreement saved. Your analytics preference could not be stored; analytics is off by default.'}location.href='/'}catch(error){$('#legal-message').textContent=error.message;$('#accept-button').disabled=false}}
}catch(error){$('#legal-operator').textContent='Operator details are temporarily unavailable.';if($('#legal-message'))$('#legal-message').textContent=error.message}
})();
